import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor(int(features[0] > 0))
    error_mask = torch.tensor(int(ctx.index) % 3 == 0)
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(targets), "error_mask": synth.Tensor(error_mask)}
ds = synth.Spec("jtt-stage-two", generator=samples, size=16, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
class Classifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=2)
    def forward(self, inputs):
        return {"logits": self.network(inputs)}
trainer = Trainer(Classifier(), train, recipe="structured-objective", recipe_config={"loss": "jtt", "loss_kwargs": {"lambda_up": 3.0}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}, "error_mask": {"batch": "error_mask"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
